#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int main()
{
    int t;
    cin >> t; cin.ignore();
    int n;
    cin >> n; cin.ignore();
    bool arr[n];
    bool s = false;
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p; cin.ignore();
        if (p >= t)
        {
            cout << "keep" << endl;
            arr[i] = true;
        }
        else
        {
            cout << "discard" << endl;
            arr[i] = false;
        }
    }
    for (int i = 0; i < n; i++)
    {
        if (arr[i] == true)
        {
            if (s)
            {
                cout << ' ';
            }
            cout << i;
            s = true;
        }
    }
    if (s)
    {
        cout << endl;
    }
    return 0;
}
